std::size_t joint_packet_raw_cache_bytes(){std::size_t total=0;auto sum=[&](const auto&cache){for(const auto&item:cache)total+=item.second.capacity();};sum(raw_array_cache<double>());sum(raw_array_cache<std::int64_t>());sum(raw_array_cache<std::uint16_t>());sum(raw_array_cache<std::uint8_t>());sum(raw_array_cache<std::uint32_t>());sum(raw_array_cache<std::int32_t>());sum(raw_array_cache<std::int8_t>());sum(raw_array_cache<std::uint64_t>());return total;}
void release_joint_packet_raw_cache(){raw_array_cache<double>().clear();raw_array_cache<std::int64_t>().clear();raw_array_cache<std::uint16_t>().clear();raw_array_cache<std::uint8_t>().clear();raw_array_cache<std::uint32_t>().clear();raw_array_cache<std::int32_t>().clear();raw_array_cache<std::int8_t>().clear();raw_array_cache<std::uint64_t>().clear();}

